extern "C" __declspec(dllexport) std::int32_t SF_ImageSpaceManager_Effects(RE::ImageSpaceManager* self, RE::ImageSpaceEffect ** buffer, std::int32_t capacity) {
    auto&& container = self->effects;
    std::int32_t total = 0;
    for (const auto& entry : SF_SlotsInUse(container)) {
        if (total < capacity) { buffer[total] = entry; }
        ++total;
    }
    return total;
}
extern "C" __declspec(dllexport) std::int32_t SF_ImageSpaceManager_GetAllEffects(RE::ImageSpaceManager::ImageSpaceEffectEnum* buffer, std::int32_t capacity) {
    auto&& container = RE::ImageSpaceManager::GetAllEffects();
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = entry; }
        ++total;
    }
    return total;
}
