extern "C" __declspec(dllexport) std::int32_t SF_ImageSpaceManager_GetImageSpaceEffectName(RE::ImageSpaceManager::ImageSpaceEffectEnum a0, char* buffer, std::int32_t capacity) {
    auto built = RE::ImageSpaceManager::GetImageSpaceEffectName(a0);
    auto total = static_cast<std::int32_t>(built.size());
    if (total > 0 && total <= capacity) { std::memcpy(buffer, built.c_str(), static_cast<std::size_t>(total)); }
    return total;
}
