extern "C" __declspec(dllexport) std::int32_t SF_MemoryManager_Heaps(RE::MemoryManager* self, RE::IMemoryHeap ** buffer, std::int32_t capacity) {
    auto* entries = self->heaps;
    std::int32_t total = static_cast<std::int32_t>(self->numHeaps);
    if (!entries || total <= 0) { return 0; }
    for (std::int32_t i = 0; i < total && i < capacity; ++i) {
        const auto& entry = entries[i];
        buffer[i] = entry;
    }
    return total;
}
extern "C" __declspec(dllexport) bool SF_MemoryManager_Heaps_Set(RE::MemoryManager* self, RE::IMemoryHeap ** entries, std::int32_t count) {
    using Entry = RE::IMemoryHeap *;
    using Count = std::remove_cvref_t<decltype(self->numHeaps)>;
    if (count < 0 || std::cmp_greater(count, (std::numeric_limits<Count>::max)()) || (count > 0 && !entries)) { return false; }
    auto* replacement = count > 0 ? static_cast<Entry*>(RE::malloc(sizeof(Entry) * static_cast<std::size_t>(count))) : nullptr;
    if (count > 0 && !replacement) { return false; }
    for (std::int32_t i = 0; i < count; ++i) { std::construct_at(replacement + i, entries[i]); }
    self->heaps = replacement;
    self->numHeaps = static_cast<Count>(count);
    return true;
}
