extern "C" __declspec(dllexport) std::int32_t SF_BGSDebrisData_TextureIDs(RE::BGSDebrisData* self, const RE::BSResource::ID** buffer, std::int32_t capacity) {
    auto&& container = self->textureIDs;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = &entry; }
        ++total;
    }
    return total;
}
