extern "C" __declspec(dllexport) bool SF_BGSDebrisData_TextureIDs_RemoveAt(RE::BGSDebrisData* self, std::int32_t index) { if (index >= 0 && static_cast<std::size_t>(index) < self->textureIDs.size()) { self->textureIDs.erase(self->textureIDs.begin() + index); return true; } return false; }
extern "C" __declspec(dllexport) void SF_BGSDebrisData_TextureIDs_PushBack(RE::BGSDebrisData* self, const RE::BSResource::ID* value) { if (value) { self->textureIDs.push_back(*value); } }
