extern "C" __declspec(dllexport) std::int32_t SF_BGSLargeRefData_FormIDCellMap(RE::BGSLargeRefData* self, SF_Entry_uint_CellID* buffer, std::int32_t capacity) {
    auto&& container = self->formIDCellMap;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = { entry.first, &entry.second }; }
        ++total;
    }
    return total;
}
