extern "C" __declspec(dllexport) std::int32_t SF_BGSQuestInstanceText_StringData(RE::BGSQuestInstanceText* self, const RE::BGSQuestInstanceText::StringData** buffer, std::int32_t capacity) {
    auto&& container = self->stringData;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = &entry; }
        ++total;
    }
    return total;
}
