extern "C" __declspec(dllexport) std::int32_t SF_Crime_ActorsKnowOfCrime(RE::Crime* self, RE::Actor** buffer, std::int32_t capacity) {
    auto&& container = self->actorsKnowOfCrime;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (auto* named = [](const auto& handle) { return handle.get().get(); }(entry)) {
            if (total < capacity) { buffer[total] = named; }
            ++total;
        }
    }
    return total;
}
