extern "C" __declspec(dllexport) std::int32_t SF_DismemberedLimb_Objects(RE::DismemberedLimb* self, RE::TESForm ** buffer, std::int32_t capacity) {
    auto&& container = self->objects;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = entry; }
        ++total;
    }
    return total;
}
