extern "C" __declspec(dllexport) std::int32_t SF_ExtraDataList_ExtraData(RE::ExtraDataList* self, const RE::BSExtraData** buffer, std::int32_t capacity) {
    auto&& container = *self;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = &entry; }
        ++total;
    }
    return total;
}
