extern "C" __declspec(dllexport) std::int32_t SF_MagicCaster_Sounds(RE::MagicCaster* self, const RE::BSSoundHandle** buffer, std::int32_t capacity) {
    auto&& container = self->sounds;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = &entry; }
        ++total;
    }
    return total;
}
