extern "C" __declspec(dllexport) std::int32_t SF_MagicTarget_GetActiveEffectList(RE::MagicTarget* self, RE::ActiveEffect ** buffer, std::int32_t capacity) {
    auto* container = self->GetActiveEffectList();
    if (!container) { return 0; }
    std::int32_t total = 0;
    for (const auto& entry : *container) {
        if (total < capacity) { buffer[total] = entry; }
        ++total;
    }
    return total;
}
extern "C" __declspec(dllexport) void* SF_MagicTarget_GetActiveEffectListNative(RE::MagicTarget* self) { return self->GetActiveEffectListNative(); }
extern "C" __declspec(dllexport) std::int32_t SF_MagicTarget_ForEachActiveEffect(RE::MagicTarget* self, RE::ActiveEffect** buffer, std::int32_t capacity) {
    struct Collector final : RE::MagicTarget::ForEachActiveEffectVisitor {
        Collector(RE::ActiveEffect** a_buffer, std::int32_t a_capacity) : buffer(a_buffer), capacity(a_capacity) {}
        RE::BSContainer::ForEachResult Accept(RE::ActiveEffect * entry) override {
            if (total < capacity) { buffer[total] = entry; }
            ++total;
            return RE::BSContainer::ForEachResult::kContinue;
        }
        RE::ActiveEffect** buffer;
        std::int32_t capacity;
        std::int32_t total = 0;
    } collector(buffer, capacity);
    self->ForEachActiveEffect(collector);
    return collector.total;
}
