extern "C" __declspec(dllexport) std::int32_t SF_W32__GUID_Data4(REX::W32::GUID* self, unsigned char* buffer, std::int32_t capacity) {
    auto&& container = self->data4;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = entry; }
        ++total;
    }
    return total;
}
extern "C" __declspec(dllexport) bool SF_W32__GUID_Data4_Set(REX::W32::GUID* self, std::int32_t index, unsigned char value) { if (index >= 0 && static_cast<std::size_t>(index) < std::size(self->data4)) { self->data4[index] = value; return true; } return false; }
