extern "C" __declspec(dllexport) std::int32_t SF_BGSConstructFormsInAllFilesMap_Files(RE::BGSConstructFormsInAllFilesMap* self, SF_Entry_TESFile_BGSConstructFormsInFileMap* buffer, std::int32_t capacity) {
    auto&& container = self->files;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = { entry.first, &entry.second }; }
        ++total;
    }
    return total;
}
extern "C" __declspec(dllexport) void SF_BGSImpactManager__SoundHandlePool_Delete(RE::BGSImpactManager::SoundHandlePool* self) { SF_DeleteOnGameHeap(self); }
extern "C" __declspec(dllexport) std::int32_t SF_BGSImpactManager__SoundHandlePool_Entries(RE::BGSImpactManager::SoundHandlePool* self, const RE::BGSImpactManager::SoundHandlePool::HandleEntry** buffer, std::int32_t capacity) {
    auto&& container = self->entries;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = &entry; }
        ++total;
    }
    return total;
}
