extern "C" __declspec(dllexport) std::int32_t SF_BSAnimationGraphVariableCache_VariableCache(RE::BSAnimationGraphVariableCache* self, const RE::AnimVariableCacheInfo** buffer, std::int32_t capacity) {
    auto&& container = self->variableCache;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = &entry; }
        ++total;
    }
    return total;
}
