extern "C" __declspec(dllexport) std::int32_t SF_NiFrustumPlanes_CullingPlanes(RE::NiFrustumPlanes* self, const RE::NiPlane** buffer, std::int32_t capacity) {
    auto&& container = self->cullingPlanes;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = &entry; }
        ++total;
    }
    return total;
}
