extern "C" __declspec(dllexport) std::int32_t SF_RaceComponent_Sliders(RE::RaceComponent* self, const RE::RaceMenuSlider** buffer, std::int32_t capacity) {
    auto&& container = self->sliders;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = &entry; }
        ++total;
    }
    return total;
}
