extern "C" __declspec(dllexport) bool SF_RaceComponent_Sliders_RemoveAt(RE::RaceComponent* self, std::int32_t index) { if (index >= 0 && static_cast<std::size_t>(index) < self->sliders.size()) { self->sliders.erase(self->sliders.begin() + index); return true; } return false; }
