extern "C" __declspec(dllexport) std::int32_t SF_hkbGeneratorOutput__Tracks_TrackHeaders(RE::hkbGeneratorOutput::Tracks* self, const RE::hkbGeneratorOutput::TrackHeader** buffer, std::int32_t capacity) {
    auto&& container = self->trackHeaders;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = &entry; }
        ++total;
    }
    return total;
}
