extern "C" __declspec(dllexport) std::int32_t SF_ExtraMissingRefIDs_IDs(RE::ExtraMissingRefIDs* self, const RE::ActivateParentID** buffer, std::int32_t capacity) {
    auto* entries = self->IDs;
    std::int32_t total = static_cast<std::int32_t>(self->numIDs);
    if (!entries || total <= 0) { return 0; }
    for (std::int32_t i = 0; i < total && i < capacity; ++i) {
        const auto& entry = entries[i];
        buffer[i] = &entry;
    }
    return total;
}
extern "C" __declspec(dllexport) bool SF_ExtraMissingRefIDs_IDs_Set(RE::ExtraMissingRefIDs* self, const RE::ActivateParentID** entries, std::int32_t count) {
    using Entry = std::remove_pointer_t<std::remove_reference_t<decltype(self->IDs)>>;
    static_assert(std::is_copy_constructible_v<Entry>, "A replaceable run stores objects that can be copied.");
    using Count = std::remove_cvref_t<decltype(self->numIDs)>;
    if (count < 0 || std::cmp_greater(count, (std::numeric_limits<Count>::max)()) || (count > 0 && !entries)) { return false; }
    auto* replacement = count > 0 ? static_cast<Entry*>(RE::malloc(sizeof(Entry) * static_cast<std::size_t>(count))) : nullptr;
    if (count > 0 && !replacement) { return false; }
    for (std::int32_t i = 0; i < count; ++i) { std::construct_at(replacement + i, *entries[i]); }
    self->IDs = replacement;
    self->numIDs = static_cast<Count>(count);
    return true;
}
