extern "C" __declspec(dllexport) std::int32_t SF_TESWorldSpace_OverlappedMultiboundMap(RE::TESWorldSpace* self, SF_Entry_uint_ObjectReference* buffer, std::int32_t capacity) {
    auto* container = self->overlappedMultiboundMap;
    if (!container) { return 0; }
    std::int32_t total = 0;
    for (const auto& outer : *container) {
        if (outer.second) {
            for (const auto& entry : *outer.second) {
                if (total < capacity) { buffer[total] = { outer.first, entry }; }
                ++total;
            }
        }
    }
    return total;
}
