extern "C" __declspec(dllexport) std::int32_t SF_NiColorData_Keys(RE::NiColorData* self, const RE::NiColorKey** buffer, std::int32_t capacity) {
    auto* entries = self->keys;
    std::int32_t total = static_cast<std::int32_t>(self->numKeys);
    if (!entries || total <= 0) { return 0; }
    for (std::int32_t i = 0; i < total && i < capacity; ++i) {
        const auto& entry = entries[i];
        buffer[i] = &entry;
    }
    return total;
}
