extern "C" __declspec(dllexport) std::int32_t SF_FOCollisionListener_DamageImpacts(RE::FOCollisionListener* self, const RE::FOCollisionListener::ObjectDamageImpactData** buffer, std::int32_t capacity) {
    auto&& container = self->damageImpacts;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = &entry; }
        ++total;
    }
    return total;
}
