extern "C" __declspec(dllexport) std::int32_t SF_TESObjectDOOR_RandomTeleports(RE::TESObjectDOOR* self, RE::TESForm ** buffer, std::int32_t capacity) {
    auto&& container = self->randomTeleports;
    std::int32_t total = 0;
    for (const auto& entry : container) {
        if (total < capacity) { buffer[total] = entry; }
        ++total;
    }
    return total;
}
